export const SUPPORT={email:'gbosheabisoye.ag@gmail.com',booking:'https://calendar.app.google/rhwGJ6n3zaRy5tdr8',linkedin:'https://www.linkedin.com/messaging/compose/?recipient=f-abisoye-gboshe-b4571a198'};
export const MCP_ENDPOINT='https://cyakphnpljeesotbjerz.supabase.co/functions/v1/pull-mcp';
const e=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const tokenPattern=/^pull_agent_[A-Za-z0-9_-]{43}$/;
export const clients=[
 {id:'claude-code',name:'Claude Code',letter:'C',status:'Ready to set up',kind:'ready',doc:'https://code.claude.com/docs/en/mcp',steps:['Create your private access key below.','Copy the command into the terminal where Claude Code is installed.','Open Claude Code, run /mcp, and check that Pull is available.'],image:'guides/terminal-setup.svg'},
 {id:'cursor',name:'Cursor',letter:'↗',status:'Ready to set up',kind:'ready',doc:'https://docs.cursor.com/context/model-context-protocol',steps:['Create your private access key below.','Open Cursor’s MCP settings. Add the Pull entry to your personal ~/.cursor/mcp.json. Merge it with existing entries.','Save, enable Pull, and check the tools list in Cursor.'],image:'guides/editor-setup.svg'},
 {id:'codex',name:'Codex',letter:'⌘',status:'Ready to set up',kind:'ready',doc:'https://developers.openai.com/codex/mcp/',steps:['Create your private access key below.','Add the configuration to your personal ~/.codex/config.toml. Keep existing server entries.','Restart Codex and check Pull in MCP settings or /mcp.'],image:'guides/editor-setup.svg'},
 {id:'claude',name:'Claude',letter:'C',status:'Requires request headers',kind:'conditional',doc:'https://claude.com/docs/connectors/custom/add-unlisted#authenticate-with-request-headers',steps:['Open Customize → Connectors → Add custom connector. Paste the Pull address.','If Request headers is available, choose No sign-in and add Authorization with the full Bearer value below. Pull still requires your private key.','Add the connector and enable it in your conversation. Use a personal connector; a shared credential grants its holders your selected access.'],image:'guides/claude-setup.svg'},
 {id:'chatgpt',name:'ChatGPT',letter:'◎',status:'OAuth setup required',kind:'pending',doc:'https://help.openai.com/en/articles/12584461-developer-mode-and-mcp-apps-in-chatgpt',steps:['Custom apps are managed from ChatGPT’s app and developer settings where available.','This Pull release uses private keys. A compatible OAuth sign-in flow still needs to be implemented for ChatGPT.','Use Claude Code, Cursor, or Codex now. Do not select No authentication for a private Pull workspace.'],image:'guides/chatgpt-setup.svg'},
 {id:'other',name:'Other agent',letter:'+',status:'Check client support',kind:'ready',doc:'https://modelcontextprotocol.io/specification/2025-06-18/basic/transports',steps:['Check that your agent supports remote MCP over Streamable HTTP with custom Authorization headers.','Add the server address and Bearer authorization value below to its private connection settings.','Refresh its tools and ask for a summary of your saved Pull workspace.'],image:'guides/editor-setup.svg'}
];
export function clientConfiguration(id,endpoint,token){
 const url=new URL(endpoint);if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash)throw new Error('Use a secure MCP endpoint.');
 if(!tokenPattern.test(token))throw new Error('Create a Pull access key first.');
 if(id==='claude-code')return `claude mcp add --scope user --transport http pull '${url.href}' --header 'Authorization: Bearer ${token}'`;
 if(id==='codex')return `[mcp_servers.pull]\nurl = ${JSON.stringify(url.href)}\nhttp_headers = { Authorization = ${JSON.stringify('Bearer '+token)} }`;
 if(id==='claude')return 'Bearer '+token;
 return JSON.stringify({mcpServers:{pull:{type:'http',url:url.href,headers:{Authorization:'Bearer '+token}}}},null,2);
}
const button=(action,label,style='secondary',disabled=false)=>`<button type="button" class="button ${style}" data-connect-action="${action}" ${disabled?'disabled':''}>${label}</button>`;
export function createConnectExperience({getCloud,getWorkspace,request,getAccountTicket,isAccountCurrent,navigate,toast,account,render}){
 let selected='claude-code',endpoint=MCP_ENDPOINT,tokens=[],loadedFor=null,loading=false,busy=false,error='',secret=null,checked=false,tools=[],confirmHeaders=false,activeView='',generation=0,refreshId=0,actionId=0;
 const chosen=()=>clients.find(c=>c.id===selected)||clients[0];
 const repaint=()=>{if(['connect','support'].includes(activeView))render();};
 const clearSecret=()=>{secret=null;checked=false;tools=[];};
 const accountReady=()=>Boolean(getCloud().user&&getCloud().verified);
 const current=(ticket,started)=>generation===started&&isAccountCurrent(ticket);
 function leave(){generation++;refreshId++;loading=false;loadedFor=null;clearSecret();activeView='';}
 async function refresh(){
  if(loading||!accountReady()||activeView!=='connect')return;const ticket=getAccountTicket(),started=generation,operation=++refreshId;loading=true;error='';
  try{const result=await request('agents',undefined,ticket.id);if(!current(ticket,started))return;if(result.configured===false)throw new Error('Agent access is not configured on this deployment.');const u=new URL(result.endpoint);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw new Error('The agent address is unavailable.');endpoint=u.href;tokens=Array.isArray(result.tokens)?result.tokens:[];loadedFor=ticket.id;}
  catch(err){if(current(ticket,started)){error=err.message;loadedFor=null;}}
  finally{if(operation===refreshId){loading=false;repaint();}}
 }
 function renderConnect(){
  const client=chosen(),cloud=getCloud(),ready=accountReady(),canCreate=ready&&loadedFor===cloud.user?.id&&client.kind!=='pending'&&(client.kind!=='conditional'||confirmHeaders),currentSecret=ready&&secret&&secret.client===selected;
  return `<div class="connect-experience"><section class="connect-intro"><span class="connect-kicker">YOUR TOOLS. YOUR WORKSPACE.</span><h2>Bring Pull into your AI.</h2><p>Give your assistant the context you’ve already built. Choose what it can access, then keep working where you feel at home.</p><div class="connect-capabilities"><span>Read your saved brief</span><span>Review your shortlist</span><span>Suggest drafts with permission</span><span>Relay conversations with permission</span></div></section><div class="connect-layout"><section class="connect-main"><div class="connect-step-heading"><span>01</span><div><h3>Choose your assistant</h3><p>We’ll show the steps for your tool.</p></div></div><div class="client-picker" role="group" aria-label="Choose your AI client">${clients.map(c=>`<button type="button" class="client-choice ${selected===c.id?'selected':''}" data-connect-client="${c.id}" aria-pressed="${selected===c.id}"><span class="client-monogram" aria-hidden="true">${e(c.letter)}</span><strong>${e(c.name)}</strong><small>${e(c.status)}</small></button>`).join('')}</div><div class="connect-client-summary"><h3>${e(client.name)} setup</h3><a href="${client.doc}" target="_blank" rel="noopener noreferrer">Official guide ↗</a></div>${client.kind==='conditional'?'<div class="connection-notice"><strong>Check for Request headers first.</strong><p>Claude offers this feature to a limited set of organizations. If it is absent, use one of the other supported clients.</p><label class="checkbox-label"><input id="connect-headers" type="checkbox" '+(confirmHeaders?'checked':'')+'><span>I can see Request headers in my Claude connector settings.</span></label></div>':''}${client.kind==='pending'?'<div class="connection-notice"><strong>ChatGPT connection is not enabled in this release.</strong><p>Pull’s OAuth sign-in is still required. The address alone cannot authenticate a private workspace.</p>'+button('use-codex','Set up Codex instead')+'</div>':''}<ol class="connect-instructions">${client.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><figure class="connect-visual"><img src="${client.image}" alt="${e(client.name)} setup illustration: choose a connector, provide the address and required authentication, then inspect the available tools." loading="lazy" width="1000" height="380"><figcaption>Illustrated guide · interface labels can vary by app version.</figcaption></figure><div class="connect-step-heading"><span>02</span><div><h3>Copy your connection details</h3><p>The address is public. Your access key keeps your workspace private.</p></div></div><label class="connect-label" for="connect-endpoint">Pull MCP address</label><div class="connect-copy-row"><input id="connect-endpoint" readonly value="${e(endpoint)}" spellcheck="false">${button('copy-url','Copy address')}</div><div class="connect-access-state" role="status">${loading?'Checking account access…':!ready?'Sign in to create access for your own saved workspace.':loadedFor===cloud.user?.id?'Your account is ready to create an agent connection.':'Check your account connection to continue.'}</div>${!ready?button('account','Sign in to continue','primary'):''}${ready&&loadedFor!==cloud.user?.id?button('refresh','Check account access'):''}${error?`<p class="connect-error" role="alert">${e(error)}</p>`:''}${client.kind!=='pending'?`<form id="connect-create"><div class="field"><label for="connect-label">Name this connection</label><input id="connect-label" name="label" maxlength="80" value="${e(client.name)} · Pull" required></div><fieldset class="connect-permissions"><legend>What can this assistant do?</legend><label><input type="radio" name="permission" value="read" checked><span><strong>Read my workspace</strong><small>Saved brief and reviewed prospects. Recommended to start.</small></span></label><label><input type="radio" name="permission" value="draft"><span><strong>Read and suggest drafts</strong><small>Can create or replace editable drafts for reviewed prospects. Nothing is sent.</small></span></label><label><input type="radio" name="permission" value="chat"><span><strong>Read and answer Pull conversations</strong><small>When you start a relay in your agent, it can answer questions inside Pull AI Mode. Your agent supplies the model; Pull does not.</small></span></label></fieldset><button class="button primary" type="submit" ${!canCreate||busy||secret?'disabled':''}>${busy?'Working…':secret?'Access key created':'Create private access key'}</button><p class="connect-fine">Expires after 30 days. You can revoke access at any time. Save your workspace to the cloud before asking your assistant to read it.</p></form>`:''}${currentSecret?`<section class="connect-secret"><div><span class="connect-kicker">SHOWN ONCE</span><h3>Your private setup is ready.</h3><p>Copy this into your client’s private settings. Keep it out of shared repositories and AI chat messages.</p></div><label class="connect-label" for="connect-configuration">${selected==='claude-code'?'Terminal command':selected==='claude'?'Authorization header value':'Client configuration'}</label><textarea id="connect-configuration" readonly rows="${selected==='claude-code'||selected==='claude'?3:8}" spellcheck="false">${e(clientConfiguration(selected,endpoint,secret.token))}</textarea><div class="connect-actions">${button('copy-config',selected==='claude-code'?'Copy command':'Copy configuration','primary')}${button('clear-secret','I’ve saved it')}</div><p class="connect-fine">Leaving this page clears the displayed key. Your active connection stays listed below.</p></section>`:''}<div class="connect-step-heading"><span>03</span><div><h3>Check, then try it</h3><p>Confirm Pull accepts your key, then check your agent’s tools list.</p></div></div><div class="connect-test"><div><strong>${checked?'Server check passed':'Verify your connection'}</strong><p>${checked?'The server accepted your key and returned '+tools.length+' tools. Your client still needs to complete its setup.':'Create a key above, then run a real server check. This does not read your prospect data.'}</p></div>${button('test',busy?'Checking…':'Test access','secondary',!currentSecret||busy)}</div><div class="connect-prompt"><span>YOUR FIRST PROMPT</span><p>“Start a Pull conversation relay: check get_pull_question for my questions, answer each one with answer_pull_question, and keep checking while this session is open. Use my known voice and preferences when relevant, respect useWorkspace, and tell me when you stop.”</p>${button('copy-prompt','Copy prompt')}</div></section><aside class="connect-aside"><section class="connect-trust"><div class="connect-trust-symbol" aria-hidden="true">↗</div><h3>Your context travels.<br>Your control stays.</h3><p>Your assistant can use only the permissions you choose. A source link remains a reference to check, and suggested drafts stay in your workspace for review.</p><dl><div><dt>Access</dt><dd>One workspace</dd></div><div><dt>Key lifetime</dt><dd>30 days</dd></div><div><dt>Outreach</dt><dd>Review before use</dd></div></dl></section><section class="connect-help"><h3>A little help getting set up?</h3><p>Send Abisoye a question or book a walkthrough.</p><button class="link-button" data-view="support">Talk to us ↗</button></section></aside></div><section class="connected-list"><div class="connect-client-summary"><div><h3>Access you’ve created</h3><p>These are active keys, not confirmation that an external app is connected.</p></div>${button('refresh','Refresh')}</div>${tokens.length?tokens.map(t=>`<div class="connected-row"><div><strong>${e(t.label||'Agent')}</strong><small>${t.scopes?.includes('chat:relay')?'Read + conversation relay':t.scopes?.includes('drafts:write')?'Read + draft suggestions':'Read only'} · expires ${e(new Date(t.expires_at).toLocaleDateString())}</small></div>${button('revoke-'+t.id,'Revoke access')}</div>`).join(''):'<p class="connect-fine">No active keys loaded. Your existing client connections appear after signing in.</p>'}<button class="link-button" data-action="agents">Advanced access controls</button></section><section class="companion-tools"><h3>Use your other tools alongside Pull</h3><p>Clay, The Org, and Taplio offer their own MCP servers. Add each to a compatible assistant using that service’s account and permissions. Connecting one does not automatically connect it inside Pull.</p><div>${[['Clay','https://university.clay.com/docs/connect-to-clay-mcp'],['The Org','https://developers.theorg.com/mcp'],['Taplio','https://intercom.help/taplio/en/articles/15532514-getting-started-with-the-taplio-mcp']].map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} setup ↗</a>`).join('')}</div></section></div>`;
 }
 function renderSupport(){return `<div class="support-experience"><section class="support-intro"><span class="connect-kicker">A PERSON BEHIND THE PRODUCT</span><h2>Let’s make your next<br>move easier.</h2><p>Have a question about your workspace, a connection, or where to start? Reach Abisoye directly.</p><div class="support-person"><span aria-hidden="true">AG</span><div><strong>Abisoye Gboshe</strong><small>Pull GTM</small></div></div></section><div class="support-options"><section class="support-option"><span class="support-option-icon" aria-hidden="true">✉</span><h3>Send a question</h3><p>Tell me what you were trying to do and where you got stuck.</p><a class="button primary" href="mailto:${SUPPORT.email}?subject=Pull%20GTM%20support">Email Abisoye ↗</a><a class="support-address" href="mailto:${SUPPORT.email}">${SUPPORT.email}</a></section><section class="support-option support-booking"><span class="support-option-icon" aria-hidden="true">↗</span><h3>Work through it together</h3><p>Choose an available time in my booking calendar for a Pull walkthrough.</p><a class="button primary" href="${SUPPORT.booking}" target="_blank" rel="noopener noreferrer">Choose a meeting time ↗</a><small>Google’s booking page shows current availability and time zone.</small></section><section class="support-option"><span class="support-option-icon" aria-hidden="true">in</span><h3>Prefer LinkedIn?</h3><p>Open a message to Abisoye in LinkedIn.</p><a class="button secondary" href="${SUPPORT.linkedin}" target="_blank" rel="noopener noreferrer">Open LinkedIn message ↗</a><small>LinkedIn may require sign-in or a connection. If the recipient is not selected, choose Abisoye Gboshe in the composer.</small></section></div><div class="support-note"><strong>Make it easy to help.</strong><p>Include the page and steps that led to the issue. Keep access keys, passwords, and your prospect list out of the message.</p></div><div class="support-shortcuts"><h3>Looking for setup help?</h3><button class="link-button" data-view="connect">Connect your AI ↗</button><button class="link-button" data-view="settings">Workspace settings ↗</button></div></div>`;}
 async function copy(value,label){try{await navigator.clipboard.writeText(value);toast(label);}catch{toast('Copy is unavailable. Select the text and copy it with your keyboard.');}}
 document.addEventListener('change',event=>{if(event.target.id==='connect-headers'){confirmHeaders=event.target.checked;repaint();}});
 document.addEventListener('click',async event=>{
  const target=event.target.closest('button');if(!target||!target.closest('.connect-experience')||activeView!=='connect')return;
  if(target.dataset.connectClient){if(busy||!clients.some(c=>c.id===target.dataset.connectClient))return;if(secret&&!window.confirm('The displayed key will be cleared. Have you saved it in your client?'))return;selected=target.dataset.connectClient;clearSecret();error='';repaint();return;}
  const action=target.dataset.connectAction;if(!action)return;
  if(action==='account'){account();return;}
  if(action==='use-codex'){if(busy)return;selected='codex';clearSecret();error='';repaint();return;}
  if(action==='copy-url'){await copy(endpoint,'MCP address copied. Your access key is separate.');return;}
  if(action==='copy-prompt'){await copy('Start a Pull conversation relay: call get_pull_question for my questions, answer each one with answer_pull_question, and keep checking while this session is open. Use my known voice and preferences when relevant, respect useWorkspace, and tell me when you stop.','Relay prompt copied.');return;}
  if(action==='copy-config'&&secret&&accountReady()){await copy(clientConfiguration(selected,endpoint,secret.token),'Private setup copied. Paste it into your client settings.');return;}
  if(action==='clear-secret'){clearSecret();repaint();return;}
  if(action==='refresh'){await refresh();return;}
  if(action==='test'&&secret&&!busy){
   if(!accountReady()){clearSecret();error='Check your account connection before testing access.';repaint();return;}
   const ticket=getAccountTicket(),started=generation,operation=++actionId,key=secret.token;busy=true;error='';checked=false;tools=[];repaint();
   try{const result=await request('agents',{action:'test',token:key},ticket.id);if(!current(ticket,started)||secret?.token!==key)return;checked=result.reachable===true;tools=Array.isArray(result.tools)?result.tools:[];if(!checked)error='The server did not confirm access. Check the connection and try again.';}
   catch(err){if(current(ticket,started)){error=err.message;checked=false;tools=[];}}
   finally{if(operation===actionId){busy=false;repaint();}}return;
  }
  if(action.startsWith('revoke-')&&!busy){
   if(!accountReady()){clearSecret();error='Check your account connection before revoking access.';repaint();return;}
   const id=action.slice(7);if(!window.confirm('Revoke this key? Any client using it will lose access.'))return;
   const ticket=getAccountTicket(),started=generation,operation=++actionId;busy=true;error='';
   try{await request('agents',{action:'revoke',id},ticket.id);if(!current(ticket,started))return;if(secret?.id===id)clearSecret();toast('Access revoked.');await refresh();}
   catch(err){if(current(ticket,started))error=err.message;}
   finally{if(operation===actionId){busy=false;repaint();}}
  }
 });
 document.addEventListener('submit',async event=>{
  if(event.target.id!=='connect-create')return;event.preventDefault();if(activeView!=='connect'||busy||secret||!accountReady()||loadedFor!==getCloud().user.id||chosen().kind==='pending'||(chosen().kind==='conditional'&&!confirmHeaders))return;
  const form=new FormData(event.target),label=String(form.get('label')||'').trim();if(!label||label.length>80)return;
  const ticket=getAccountTicket(),selectedClient=selected,started=generation,operation=++actionId;busy=true;error='';repaint();
  try{const result=await request('agents',{action:'create',label,scopes:form.get('permission')==='draft'?['workspace:read','drafts:write']:form.get('permission')==='chat'?['workspace:read','chat:relay']:['workspace:read']},ticket.id);if(!current(ticket,started))return;if(!tokenPattern.test(result.token))throw new Error('No access key was returned. Refresh your connections before retrying.');secret={token:result.token,id:result.id,client:selectedClient};checked=false;await refresh();}
  catch(err){if(current(ticket,started)){error=err.message;loadedFor=null;}}
  finally{if(operation===actionId){busy=false;repaint();}}
 });
 return {renderConnect,renderSupport,afterRender(view){if(activeView==='connect'&&view!=='connect')leave();activeView=view;if(view==='connect'&&accountReady()&&!loading&&loadedFor!==getCloud().user.id&&!error)void refresh();},accountChanged(){generation++;refreshId++;actionId++;clearSecret();loadedFor=null;tokens=[];endpoint=MCP_ENDPOINT;error='';busy=false;loading=false;confirmHeaders=false;repaint();},leave};
}
